namespace sv_f6301aeec36749b9a88733862fa105e6.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_f6301aeec36749b9a88733862fa105e6.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-description">@TruncatedDescription</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnClick { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 40
            ? Channel.Description[..40] + "…"
            : Channel.Description;
}

@using sv_f6301aeec36749b9a88733862fa105e6.Services

<div class="channel-sidebar">
    <h3 class="sidebar-title">Channels</h3>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@using sv_f6301aeec36749b9a88733862fa105e6.Services

<div class="message-bubble" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ThreadReplyCount > 0)
    {
        <div class="thread-link" @onclick="() => OnOpenThread.InvokeAsync()">
            @ThreadReplyCount replies
        </div>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync()" title="Reply in thread">💬 Reply</button>
            <div class="emoji-picker-container">
                <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">😀 React</button>
                @if (showEmojiPicker)
                {
                    <div class="emoji-picker">
                        @foreach (var emoji in CommonEmojis)
                        {
                            <span class="emoji-option" @onclick="() => SelectEmoji(emoji)">@emoji</span>
                        }
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ThreadReplyCount { get; set; }
    [Parameter] public EventCallback OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private static readonly string[] CommonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@using sv_f6301aeec36749b9a88733862fa105e6.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h2># @Channel.Name</h2>
            <p>@Channel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @foreach (var message in Messages)
            {
                <MessageBubble Message="message"
                               ThreadReplyCount="GetThreadReplyCount(message.Id)"
                               OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                               OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <div class="message-input-area">
            <textarea class="message-textarea"
                      @bind="newMessageText"
                      @bind:event="oninput"
                      placeholder="Message #@Channel.Name"
                      @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">Send</button>
        </div>
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private string newMessageText = string.Empty;

    private int GetThreadReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — parent handles pagination logic
        await OnLoadMore.InvokeAsync();
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText;
        newMessageText = string.Empty;
        await OnSendMessage.InvokeAsync(text);
    }
}

@using sv_f6301aeec36749b9a88733862fa105e6.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <div class="thread-input-area">
            <textarea class="message-textarea"
                      @bind="replyText"
                      @bind:event="oninput"
                      placeholder="Reply…"
                      @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(replyText)">Reply</button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private string replyText = string.Empty;

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendReply();
        }
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(replyText)) return;
        var text = replyText;
        replyText = string.Empty;
        await OnReply.InvokeAsync(text);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@page "/chat"
@using sv_f6301aeec36749b9a88733862fa105e6.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "thread-open" : "")">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="LoadMoreMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private List<Message> threadReplies = new();

    private Channel? selectedChannel;
    private int? selectedChannelId;
    private Message? threadRootMessage;
    private bool threadOpen;
    private bool isLoadingMore;

    private const int PageSize = 30;
    private int currentSkip;
    private bool allMessagesLoaded;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        allMessagesLoaded = false;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new ThreadSummary(
                m.Id,
                messages.Count(r => r.ReplyToId == m.Id),
                messages.Where(r => r.ReplyToId == m.Id).Select(r => r.SentAt).DefaultIfEmpty(m.SentAt).Max()))
            .Where(t => t.ReplyCount > 0)
            .ToList();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }

        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || allMessagesLoaded || selectedChannelId is null) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, currentSkip, PageSize);
        if (older.Count < PageSize)
        {
            allMessagesLoaded = true;
        }
        messages.InsertRange(0, older);
        currentSkip += older.Count;
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannelId is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary count
        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
        if (existing is not null)
        {
            threadSummaries.Remove(existing);
            threadSummaries.Add(existing with { ReplyCount = existing.ReplyCount + 1, LastReplyAt = reply.SentAt });
        }
        else
        {
            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt));
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update local state
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (reaction is not null)
            {
                reaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, new List<string> { "You" }));
            }
        }
    }
}

