.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    position: relative;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-open {
    flex: 0 0 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #36393f;
    color: #dcddde;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 8px;
    font-size: 0.85rem;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #8e9297;
    font-size: 1.1rem;
}

/* Message bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

::deep .reaction-badge:hover {
    border-color: #dcddde;
}

::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #00aff4;
    cursor: pointer;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 4px;
}

::deep .action-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .emoji-picker-container {
    position: relative;
}

::deep .emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 8px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

::deep .emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #4f545c;
}

/* Message input */
::deep .message-input-area {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

::deep .message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

::deep .message-textarea:focus {
    outline: none;
}

::deep .message-textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 8px;
    border-radius: 4px;
}

::deep .thread-reply:hover {
    background: #36393f;
}

::deep .thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

