+
+::deep .message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+    display: flex;
+    flex-direction: column;
+    gap: 4px;
+}
+
+::deep .loading-indicator {
+    text-align: center;
+    color: #8e9297;
+    padding: 8px;
+    font-size: 0.85rem;
+}
+
+::deep .no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    flex: 1;
+    color: #8e9297;
+    font-size: 1.1rem;
+}
+
+/* Message bubble */
+::deep .message-bubble {
+    padding: 8px 12px;
+    border-radius: 4px;
+    position: relative;
+}
+
+::deep .message-bubble:hover {
+    background: #32353b;
+}
+
+::deep .message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+}
+
+::deep .message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+::deep .message-time {
+    font-size: 0.7rem;
+    color: #72767d;
+}
+
+::deep .message-content {
+    margin-top: 4px;
