+    padding: 2px 6px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    display: inline-flex;
+    align-items: center;
+    gap: 4px;
+}
+
+::deep .reaction-badge:hover {
+    border-color: #dcddde;
+}
+
+::deep .thread-link {
+    margin-top: 4px;
+    font-size: 0.8rem;
+    color: #00aff4;
