+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
+
+::deep .message-textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    color: #dcddde;
+    padding: 10px 14px;
