+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+}
+
+::deep .thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .close-btn {
+    background: transparent;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+::deep .thread-reply {
+    padding: 8px;
+    border-radius: 4px;
+}
+
+::deep .thread-reply:hover {
+    background: #36393f;
+}
+
+::deep .thread-input-area {
+    padding: 12px 16px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
